import { readFile, writeFile } from 'node:fs/promises';

// The official mark is embedded unchanged apart from its white presentation
// color. Geometry matches BrandMapPinClipper at 48×56 and its 27px logo.
const logo = await readFile(new URL('../../mobile/assets/branding/only-black.svg', import.meta.url), 'utf8');
const paths = logo.match(/<path\b[^>]*\/>/g).join('\n').replaceAll('fill="black"', 'fill="white"');
const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="48" height="56" viewBox="0 0 48 56">
  <!-- Generated by scripts/generate-map-pin.mjs from the official brand mark. -->
  <path d="M24 56L16.32 45.36C-5.76 36.4 0 0 24 0C48 0 53.76 36.4 31.68 45.36Z" fill="#111111"/>
  <svg x="10.5" y="11" width="27" height="27" viewBox="0 0 374 354" fill="none">
${paths}
  </svg>
</svg>
`;
await writeFile(new URL('../public/map-location-pin.svg', import.meta.url), svg);
